// AI-generated by Claude
void MainWindow::loadImage() {
    QString fileName = QFileDialog::getOpenFileName(this, "Open Image", "", "Image Files (*.png *.jpg *.bmp)");
    if (!fileName.isEmpty()) {
        m_currentImage.loadNewImage(fileName.toStdString());
        m_isImageLoaded = true;
        updateImageDisplay();
    }
}

//***/ /***//*** //***//***//*** //

// AI-generated by Claude
void MainWindow::saveImage() {
    if (!m_isImageLoaded) {
        QMessageBox::warning(this, "Warning", "No image loaded to save.");
        return;
    }
    QString fileName = QFileDialog::getSaveFileName(this, "Save Image", "", "Image Files (*.png *.jpg *.bmp)");
    if (!fileName.isEmpty()) {
        m_currentImage.saveImage(fileName.toStdString());
        QMessageBox::information(this, "Success", "Image saved successfully!");
    }
}

