// AI-generated by Claude
void MainWindow::updateImageDisplay() {
    if (!m_isImageLoaded) return;

    int _img_width = m_currentImage.width;
    int _img_height = m_currentImage.height;

    QImage qimg(_img_width, _img_height, QImage::Format_RGB888);

    for (int _y = 0; _y < _img_height; ++_y) {
        for (int _x = 0; _x < _img_width; ++_x) {
            unsigned char r = m_currentImage.getPixel(_x, _y, 0);
            unsigned char g = m_currentImage.getPixel(_x, _y, 1);
            unsigned char b = m_currentImage.getPixel(_x, _y, 2);
            qimg.setPixelColor(_x, _y, QColor(r, g, b));
        }
    }

    m_imageLabel->setPixmap(QPixmap::fromImage(qimg).scaled(m_imageLabel->size(), Qt::KeepAspectRatio, Qt::SmoothTransformation));
}

