// AI-generated by Claude
// Every filter that needs input asks for it first. If the user cancels any
// dialog, the function returns and the image stays unchanged.
// Every case that applies a filter must end with `break;` so that
// updateImageDisplay() runs at the bottom and the screen refreshes.
void MainWindow::applySelectedFilter() {
    if (!m_isImageLoaded) {
        QMessageBox::warning(this, "Warning", "Please load an image first.");
        return;
    }

    int filterIndex = m_filterComboBox->currentIndex();
    bool ok = false;

    switch (filterIndex) {
        case 0:
            applyGrayscale_1(m_currentImage);
            break;

        case 1:
            applyBlackAndWhite_2(m_currentImage);
            break;

        case 2:
            applyInvert_3(m_currentImage);
            break;

        case 3: {   // Frame: style + color
            QStringList styles = {"Simple", "Fancy"};
            QString styleName = QInputDialog::getItem(this, "Frame Style",
                                    "Choose the frame style:", styles, 0, false, &ok);
            if (!ok) return;
            int frameType = (styleName == "Simple") ? 1 : 2;

            QColor color = QColorDialog::getColor(Qt::red, this, "Choose Frame Color");
            if (!color.isValid()) return;

            applyFrame_4(m_currentImage, frameType,
                         static_cast<unsigned char>(color.red()),
                         static_cast<unsigned char>(color.green()),
                         static_cast<unsigned char>(color.blue()));
            break;
        }

        case 4: {   // Flip: horizontal or vertical
            QStringList directions = {"Horizontal", "Vertical"};
            QString direction = QInputDialog::getItem(this, "Flip Direction",
                                    "Choose the flip direction:", directions, 0, false, &ok);
            if (!ok) return;
            applyFlip_5(m_currentImage, direction == "Horizontal");
            break;
        }

        case 5: {   // Rotate: 90 / 180 / 270
            QStringList degrees = {"90", "180", "270"};
            QString degreeText = QInputDialog::getItem(this, "Rotate Image",
                                    "Choose the rotation angle (degrees):", degrees, 0, false, &ok);
            if (!ok) return;
            applyRotate_6(m_currentImage, degreeText.toInt());
            break;
        }

        case 6: {   // Brightness: factor < 1 darkens, factor > 1 lightens
            double factor = QInputDialog::getDouble(this, "Brightness",
                                "Factor (below 1 = darken, above 1 = lighten):",
                                1.0, 0.1, 3.0, 2, &ok);
            if (!ok) return;
            applyBrightness_7(m_currentImage, factor);
            break;
        }

        case 7: {   // Resize: new width and height
            int _new_width = QInputDialog::getInt(this, "Resize Image",
                                "New width (pixels):", m_currentImage.width, 1, 10000, 1, &ok);
            if (!ok) return;
            int _new_height = QInputDialog::getInt(this, "Resize Image",
                                "New height (pixels):", m_currentImage.height, 1, 10000, 1, &ok);
            if (!ok) return;
            applyResize_8(m_currentImage, _new_width, _new_height);
            break;
        }

        case 8: {   // Merge: second image + merge type
            QString secondFile = QFileDialog::getOpenFileName(this, "Choose the Second Image",
                                    "", "Image Files (*.png *.jpg *.bmp)");
            if (secondFile.isEmpty()) return;

            Image secondImage;
            secondImage.loadNewImage(secondFile.toStdString());

            QStringList mergeTypes = {
                "1. Resize to the biggest width and height",
                "2. Merge the common area only"
            };
            QString mergeChoice = QInputDialog::getItem(this, "Merge Type",
                                    "Choose the merge type:", mergeTypes, 0, false, &ok);
            if (!ok) return;
            int mergeType = mergeTypes.indexOf(mergeChoice) + 1;

            applyMerge_9(m_currentImage, secondImage, mergeType);
            break;
        }

        case 9:
            applyDetectImageEdges_10(m_currentImage);
            break;

        case 10: {  // Crop: top-left corner (x, y) + width + height
            int _crop_x = QInputDialog::getInt(this, "Crop Image",
                                "Start X (top-left corner):", 0, 0, m_currentImage.width - 1, 1, &ok);
            if (!ok) return;
            int _crop_y = QInputDialog::getInt(this, "Crop Image",
                                "Start Y (top-left corner):", 0, 0, m_currentImage.height - 1, 1, &ok);
            if (!ok) return;
            int _crop_width = QInputDialog::getInt(this, "Crop Image",
                                "Crop width:", m_currentImage.width - _crop_x,
                                1, m_currentImage.width - _crop_x, 1, &ok);
            if (!ok) return;
            int _crop_height = QInputDialog::getInt(this, "Crop Image",
                                "Crop height:", m_currentImage.height - _crop_y,
                                1, m_currentImage.height - _crop_y, 1, &ok);
            if (!ok) return;
            applyCrop_11(m_currentImage, _crop_x, _crop_y, _crop_width, _crop_height);
            break;
        }

        case 11: {  // Blur: level
            double blurFactor = QInputDialog::getDouble(this, "Blur Image",
                                    "Blur level (higher = blurrier):", 2.0, 0.5, 20.0, 1, &ok);
            if (!ok) return;
            applyBlur_12(m_currentImage, static_cast<float>(blurFactor));
            break;
        }

        case 12:
            applySunlight_13(m_currentImage);
            break;

        case 13:
            applyOldTvscreen_14(m_currentImage);
            break;

        case 14:
            applyPurple_15(m_currentImage);
            break;

        case 15:
            applyInfrared_16(m_currentImage);
            break;

        case 16: {  // Skew: angle in degrees (signature is applySkewing_17(Image&, int))
            int angle = QInputDialog::getInt(this, "Skew Image",
                                "Skew angle (degrees):", 40, -80, 80, 1, &ok);
            if (!ok) return;
            applySkewing_17(m_currentImage, angle);
            break;
        }

        case 17: {  // Oil painting
            applyOilPainting_18(m_currentImage);
            break;
        }

        default:
            break;
    }

    updateImageDisplay();
}